import{_ as a,o as n,a as p,b as c}from"./app.BGziXukh.js";const i=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"reg矢量计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_vector_compute"},{"text":"掩码寄存器计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/mask_reg_compute/mask_reg_compute"},{"text":"mask使用说明","link":"/api/SIMD-API/tensor_api/reg_vector_compute/mask_reg_compute/mask_usage"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/reg_vector_compute/mask_reg_compute/mask_usage.md","filePath":"api/SIMD-API/tensor_api/reg_vector_compute/mask_reg_compute/mask_usage.md","outlineHeaders":[{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"初始化mask","slug":"初始化mask","link":"#初始化mask"},{"level":3,"title":"与load链式调用","slug":"与load链式调用","link":"#与load链式调用"},{"level":2,"title":"计算接口中的mask传递","slug":"计算接口中的mask传递","link":"#计算接口中的mask传递"}],"lastUpdated":1793776473000}'),e={name:"api/SIMD-API/tensor_api/reg_vector_compute/mask_reg_compute/mask_usage.md"};function o(l,s,d,t,r,m){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>mask的用法</h1><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p><code>reg_tensor&lt;DataType&gt;</code>同时保存数据寄存器<code>reg</code>和与数据关联的掩码寄存器<code>mask</code>。计算接口使用的mask与返回对象保存的mask不一定相同，具体规则见<a href="#%E8%AE%A1%E7%AE%97%E6%8E%A5%E5%8F%A3%E4%B8%AD%E7%9A%84mask%E4%BC%A0%E9%80%92">计算接口中的mask传递</a>。<code>asc::te::experimental::store</code>的单源<code>direct</code>、<code>pack</code>和<code>pack_quarter</code>模式继续使用源<code>reg_tensor</code>中保存的mask控制写回。</p><p><code>reg_tensor</code>的默认构造函数不初始化<code>reg</code>和<code>mask</code>。在接口需要读取或保留其<code>mask</code>前，必须保证该成员已初始化；否则，参与计算和写回的有效元素不确定。若计算链中的有效范围发生变化，应在下一次计算或写回前重新调用<code>with_mask</code>绑定新的mask。</p><p>当<code>DataType</code>为<code>bool</code>时，<code>reg_tensor&lt;bool&gt;</code>同样包含<code>reg</code>和<code>mask</code>两个成员。<code>all_mask</code>、<code>make_mask</code>、<code>update_mask</code>及比较接口只保证返回对象的<code>reg</code>成员有效，不应直接读取其<code>mask</code>成员。</p><h2 id="初始化mask">初始化mask<a class="header-anchor" href="#初始化mask">​</a></h2><p>可通过以下接口生成mask，类型为<code>reg_tensor&lt;bool&gt;</code>：</p><table><thead><tr><th>接口</th><th>使用场景</th></tr></thead><tbody><tr><td><code>all_mask&lt;DataType&gt;()</code></td><td>当前寄存器中的所有元素都有效。</td></tr><tr><td><code>make_mask&lt;Pattern, DataType&gt;()</code></td><td>按固定模式生成mask。</td></tr><tr><td><code>update_mask&lt;DataType&gt;(remain)</code></td><td>按剩余元素数量生成mask，通常用于处理循环中的尾块。</td></tr></tbody></table><p><code>DataType</code>必须与mask所服务的数据元素类型保持一致。例如，在给<code>reg_tensor&lt;float&gt;</code>赋值时应使用<code>all_mask&lt;float&gt;()</code>或<code>update_mask&lt;float&gt;(remain)</code>，不同元素位宽对应的有效元素数不同。</p><h3 id="与load链式调用">与load链式调用<a class="header-anchor" href="#与load链式调用">​</a></h3><p><code>load</code>和<code>load_broadcast</code>只初始化返回对象的<code>reg</code>，不初始化<code>mask</code>。推荐通过链式计算<code>with_mask</code>或在搬入后立即绑定mask：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">auto</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">update_mask</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="p">(</span><span class="n">remain</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">src0Reg</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load</span><span class="p">(</span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="n">offset</span><span class="p">)).</span><span class="n">with_mask</span><span class="p">(</span><span class="n">mask</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">src1Reg</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load</span><span class="p">(</span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="n">offset</span><span class="p">)).</span><span class="n">with_mask</span><span class="p">(</span><span class="n">mask</span><span class="p">);</span>
</code></pre></div><p>对于返回<code>reg_pair</code>的<code>deintlv</code>搬入模式，需分别为两个成员绑定mask：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">auto</span><span class="w"> </span><span class="n">srcReg</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load_sideband_mode</span><span class="o">::</span><span class="n">deintlv</span><span class="o">&gt;</span><span class="p">(</span>
<span class="w">    </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="n">offset</span><span class="p">));</span>

<span class="k">auto</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">all_mask</span><span class="o">&lt;</span><span class="kt">uint8_t</span><span class="o">&gt;</span><span class="p">();</span>
<span class="n">srcReg</span><span class="p">.</span><span class="n">first</span><span class="p">.</span><span class="n">with_mask</span><span class="p">(</span><span class="n">mask</span><span class="p">);</span>
<span class="n">srcReg</span><span class="p">.</span><span class="n">second</span><span class="p">.</span><span class="n">with_mask</span><span class="p">(</span><span class="n">mask</span><span class="p">);</span>
</code></pre></div><h2 id="计算接口中的mask传递">计算接口中的mask传递<a class="header-anchor" href="#计算接口中的mask传递">​</a></h2><p>下表列举计算使用的mask和返回对象保存的mask。若一个接口同时满足多个条件，按“已有<code>dst</code>→满mask结果→显式mask→常规接口”的顺序判定；比较运算符始终按其特殊规则处理。</p><table><thead><tr><th>规则或类别</th><th>接口或计算形式</th><th>计算使用的mask</th><th>返回对象的mask</th></tr></thead><tbody><tr><td>已有dst作为入参</td><td><code>axpy(dst, src, scalar)</code>、<code>madd(dst, src0, src1)</code>、<code>mula(dst, src0, src1)</code>、<code>fill(dst, value, mask)</code>、<code>fill(dst, src, mask)</code>、<code>move(dst, src)</code>、<code>histograms(dst, src)</code></td><td><code>axpy</code>、<code>move</code>和<code>histograms</code>使用<code>src.mask</code>；<code>madd</code>和<code>mula</code>使用<code>dst.mask</code>；<code>fill</code>使用其操作模式规定的输入或显式mask。</td><td>返回对象保留调用前的<code>dst.mask</code>。该规则优先于显式mask规则。</td></tr><tr><td>语义为按照全有效mask处理的接口</td><td><code>pack&lt;part&gt;(src)</code>、<code>unpack&lt;part&gt;(src)</code>、寄存器<code>gather(src, index)</code>、<code>expand&lt;T&gt;(mask)</code>、<code>iota&lt;order&gt;(start)</code>、数据或掩码<code>interleave(src0, src1)</code>和<code>deinterleave(src0, src1)</code>、<code>move_mask&lt;Offset&gt;(src)</code></td><td>均不使用输入对象的有效性mask；<code>expand</code>中的<code>mask.reg</code>用于生成前缀计数索引，不作为输出有效性mask。</td><td>将返回对象的mask设置为对应元素类型的全有效mask；返回<code>reg_pair</code>时两个成员均设置。</td></tr><tr><td>显式传入mask</td><td>不带<code>dst</code>的<code>fill(value, mask)</code>和<code>fill(src, mask)</code>、<code>load_gather</code></td><td>显式传入的<code>mask.reg</code>或<code>gather_mask.reg</code>。</td><td>将返回对象的mask设置为显式mask的<code>reg</code>。</td></tr><tr><td>常规接口</td><td><code>cast&lt;DstType&gt;(src)</code>、<code>muls_cast&lt;DstType&gt;(src, scalar)</code>、带<code>position</code>的<code>exp_diff</code>、<code>reduce_sum(src)</code>、<code>reduce_max(src)</code>、<code>reduce_min(src)</code>、<code>abs(src)</code>、<code>exp(src)</code>、<code>compress(src)</code>、掩码单参数<code>move(src)</code>、<code>src + scalar</code>、<code>scalar * src</code>、<code>src0 + src1</code>、<code>fma(src0, src1, src2)</code>、<code>select(condition, src0, src1)</code>、<code>add_carry</code>、<code>sub_carry</code>和<code>mull</code></td><td>单输入接口使用<code>src.mask</code>；多输入接口使用第一个数据输入<code>src0.mask</code>。</td><td>单输入接口复制<code>src.mask</code>；多输入接口复制<code>src0.mask</code>。返回<code>reg_pair</code>时，<code>first.mask</code>和<code>second.mask</code>均按相同规则设置。类型或布局变化时，不按目标位宽、结果位置或归约后的结果数量重新映射。</td></tr><tr><td>特殊：比较运算符</td><td><code>operator==</code>、<code>operator!=</code>、<code>operator&lt;</code>、<code>operator&lt;=</code>、<code>operator&gt;</code>、<code>operator&gt;=</code>的寄存器和标量重载</td><td>寄存器与寄存器比较使用<code>src0.mask</code>；与标量比较使用寄存器操作数的mask。</td><td>不初始化返回对象的mask。</td></tr></tbody></table><ul><li>按照全有效mask处理的接口返回的对象的mask为全有效，不保证返回对象的所有位置都具有可使用的数值。例如，<code>pack</code>未写入的另一半寄存器仍不应作为有效结果使用；类型转换、归约和压缩后的有效结果范围也应遵循对应接口约束，必要时在写回前重新绑定mask。</li><li>比较接口及mask生成接口的返回对象用于提供<code>reg</code>中的掩码数据，不应读取其未初始化的<code>mask</code>。需要把它们作为依赖有效性mask的输入时，应先通过<code>with_mask</code>绑定mask。</li><li>对于遵循常规多输入规则的接口，各输入的mask不会合并或校验，第二个及后续数据输入的mask不参与确定有效元素。调用前应保证所有数据输入在第一个操作数mask选中的位置均有效；为各输入绑定相同mask是常见做法。例如：</li></ul><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">auto</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">update_mask</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="p">(</span><span class="n">remain</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">src0Reg</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load</span><span class="p">(</span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="n">offset</span><span class="p">)).</span><span class="n">with_mask</span><span class="p">(</span><span class="n">mask</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">src1Reg</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load</span><span class="p">(</span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="n">offset</span><span class="p">)).</span><span class="n">with_mask</span><span class="p">(</span><span class="n">mask</span><span class="p">);</span>

<span class="k">auto</span><span class="w"> </span><span class="n">dstReg</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src0Reg</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">src1Reg</span><span class="p">;</span>
<span class="c1">// dstReg.mask与src0Reg.mask保持一致，可直接用于单源store。</span>
<span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">store</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="n">offset</span><span class="p">),</span><span class="w"> </span><span class="n">dstReg</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const _=a(e,[["render",o]]);export{i as __pageData,_ as default};
